/* Documented on nys-table: tighten the rows so the slide fits */
nys-table {
  --nys-table-padding--cell--y: var(--nys-space-100);
}

/* Each swatch reads its color from the --swatch property on the element */
.swatch {
  display: inline-block;
  inline-size: var(--nys-space-300);
  block-size: var(--nys-space-300);
  margin-inline-end: var(--nys-space-100);
  vertical-align: middle;
  border: var(--nys-border-width-sm) solid var(--nys-color-base);
  border-radius: var(--nys-radius-md);
  background: var(--swatch);
}

/* Each sample reads its size from the --step property on the element */
.samples {
  display: grid;
  gap: var(--nys-space-150);
  margin: 0;
  padding: 0;
  list-style: none;
}

.samples li {
  display: flex;
  align-items: center;
  gap: var(--nys-space-150);
  margin: 0;
}

.bar {
  inline-size: var(--step);
  block-size: var(--nys-space-200);
  background: var(--nys-color-theme);
}

.corner {
  inline-size: var(--nys-space-500);
  block-size: var(--nys-space-500);
  border: var(--nys-border-width-md) solid var(--nys-color-theme);
  border-radius: var(--step);
}

.rule {
  inline-size: var(--nys-space-600);
  border-block-start: var(--step) solid var(--nys-color-theme);
}

/* Container: border, radius, and a theme accent */
.summary {
  border: var(--nys-border-width-sm) solid var(--nys-color-theme-weak);
  border-block-start: var(--nys-border-width-lg) solid var(--nys-color-theme);
  border-radius: var(--nys-radius-lg);
  overflow: hidden; /* Clip the title band to the rounded corners */
  background: var(--nys-color-surface);
  color: var(--nys-color-text);
}

/* Clear the default margins so the utilities set the spacing */
.summary h2,
.summary dl,
.summary dd {
  margin: 0;
}

/* Title band */
.summary h2 {
  background: var(--nys-color-theme-weak);
}

/* Labels: weight has no utility class, so it comes from a token */
.summary dt {
  font-weight: var(--nys-font-weight-semibold);
}

/* A divider above each row */
.summary dl > div {
  border-block-start: var(--nys-border-width-sm) solid var(--nys-color-theme-weak);
}

/* New in this step */

/* The stylesheet already styles links. Add the state it can't know about:
   which row the keyboard is in. */
.summary dl > div:focus-within {
  background: var(--nys-color-theme-weaker);
  box-shadow: inset var(--nys-border-width-lg) 0 0 var(--nys-color-focus);
}

/* From the last step */

/* Container: border, radius, and a theme accent */
