  border-block-start: var(--nys-border-width-sm) solid var(--nys-color-theme-weak);
}

/* The same rules for all eight tiles. The class on each tile picks the palette. */
.themes {
  margin: 0;
  padding: 0;
  list-style: none;
}

/* The li is the grid column. The tile inside it carries the theme class. */
.themes li {
  margin: 0;
}

.tile {
  block-size: 100%;
  padding: var(--nys-space-200);
  border: var(--nys-border-width-sm) solid var(--nys-color-theme-weak);
  border-radius: var(--nys-radius-md);
  background: var(--nys-color-theme-faint);
  color: var(--nys-color-text);
}

/* Four steps of the theme family, drawn above each name */
.tile::before {
  content: "";
  display: block;
  block-size: var(--nys-space-400);
  margin-block-end: var(--nys-space-150);
  border-radius: var(--nys-radius-sm);
  background: linear-gradient(
    to right,
    var(--nys-color-theme-weak) 0 25%,
    var(--nys-color-theme-mid) 25% 50%,
    var(--nys-color-theme) 50% 75%,
    var(--nys-color-theme-stronger) 75%
  );
}

