}

/* Hard-coded: the same look, typed as hex and pixel values. Brief on purpose. */
.summary-hex {
  border: 1px solid #cddde9;
  border-top: 4px solid #154973;
  border-radius: 8px;
  overflow: hidden;
  background: #ffffff;
  color: #1b1b1b;
}

.summary-hex h2,
.summary-hex dl,
.summary-hex dd {
  margin: 0;
}

.summary-hex h2 {
  background: #cddde9;
}

.summary-hex dt {
  font-weight: 600;
}

.summary-hex dl > div {
  border-top: 1px solid #cddde9;
}

.summary-hex dl > div:focus-within {
  background: #eff6fb;
  box-shadow: inset 4px 0 0 #004dd1;
}

