const select = document.getElementById('theme-select');
const themed = document.getElementById('themed');

select.addEventListener('nys-change', (event) => {
  // Keep one nys-theme-* class on the wrapper at a time. Default is no class,
  // because nys-theme-default doesn't reset a parent theme in 1.23.1.
  const old = [...themed.classList].filter((name) => name.startsWith('nys-theme-'));
  themed.classList.remove(...old);
  if (event.detail.value !== 'default') {
    themed.classList.add(`nys-theme-${event.detail.value}`);
  }
});
